-- Grade 10 Advanced / Week 9: 27 FRQs, routed 6 + 11 + 10.
-- Run this complete script in the connected Neon SQL Editor.
-- Existing question edits, deletions, assignments, and all Week 8 data are preserved.
BEGIN;
CREATE TABLE IF NOT EXISTS questions(id text PRIMARY KEY,data jsonb,revision integer NOT NULL DEFAULT 1 CHECK(revision>0),deleted boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS learning_outcomes(id uuid PRIMARY KEY,classroom text NOT NULL,title text NOT NULL,title_ar text NOT NULL DEFAULT '',book_pages text NOT NULL DEFAULT '',target_count integer NOT NULL CHECK(target_count BETWEEN 1 AND 500),position integer NOT NULL CHECK(position BETWEEN 1 AND 1000),revision integer NOT NULL DEFAULT 1,deleted boolean NOT NULL DEFAULT false,last_operation uuid);
ALTER TABLE learning_outcomes ADD COLUMN IF NOT EXISTS exam_week integer NOT NULL DEFAULT 8 CHECK(exam_week BETWEEN 1 AND 52);
ALTER TABLE learning_outcomes ADD COLUMN IF NOT EXISTS assessment_item text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS outcome_questions(question_id text PRIMARY KEY REFERENCES questions(id),outcome_id uuid NOT NULL REFERENCES learning_outcomes(id),position integer NOT NULL CHECK(position>0));
INSERT INTO learning_outcomes(id,classroom,exam_week,assessment_item,title,title_ar,book_pages,target_count,position,last_operation) VALUES
('d4ab9449-ab93-409f-b9fe-73ec19c0f74f'::uuid,'10A1',9,'Q13','Use proportional parts within triangles','استخدام الأجزاء المتناسبة داخل المثلثات','146 (Q11–16)',6,1,'d4ab9449-ab93-409f-b9fe-73ec19c0f74f'::uuid),
('e0d8ee6c-0a18-4059-ab23-a56c1c913745'::uuid,'10A1',9,'Q14','Recognize and use proportional relationships of corresponding angle bisectors, altitudes, and medians of similar triangles','تمييز واستخدام العلاقات التناسبية بين منصفات الزوايا والارتفاعات والمتوسطات المتناظرة في المثلثات المتشابهة','153 (Q1–11)',11,2,'e0d8ee6c-0a18-4059-ab23-a56c1c913745'::uuid),
('8475eb8f-d882-4be3-8caf-919cfb34762d'::uuid,'10A1',9,'Q15','Find the geometric mean between two numbers','إيجاد الوسط الهندسي بين عددين','165 (Q1–6, Q11–14)',10,3,'8475eb8f-d882-4be3-8caf-919cfb34762d'::uuid)
ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,data) VALUES
('10a1-w9-p146-q11',$question_json${"id":"10a1-w9-p146-q11","classroom":"10A1","examWeek":9,"position":1,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 146 · Q11 · Proportional parts · الأجزاء المتناسبة","marks":4,"prompt":"Find x and y. The three marked lines are parallel, and the two marked segments on the left transversal are congruent. Show your equations.","promptAr":"أوجد x وy. المستقيمات الثلاثة المعلمة متوازية، والقطعتان المعلمتان على القاطع الأيسر متطابقتان. اكتب معادلتي الحل.","answer":"Equal intercepts: $2x+1=x+7$, so $x=6$. On the other transversal $3y-8=y+5$, so $2y=13$ and $y=\\frac{13}{2}=6.5$.","answerAr":"من تساوي القطع: $2x+1=x+7$، ومنه $x=6$. وعلى القاطع الآخر $3y-8=y+5$، لذلك $2y=13$ ثم $y=\\frac{13}{2}=6.5$.","diagram":"week9-geometry","geometryDiagram":{"page":146,"number":11},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":146,"sourceQuestion":11,"expectedValues":{"x":6,"y":6.5},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"},{"label":"y · قيمة y — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p146-q12',$question_json${"id":"10a1-w9-p146-q12","classroom":"10A1","examWeek":9,"position":2,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 146 · Q12 · Proportional parts · الأجزاء المتناسبة","marks":4,"prompt":"Find x and y. The inner segment is parallel to the lower side, and the two marked segments on the upper side are congruent.","promptAr":"أوجد x وy. القطعة الداخلية توازي الضلع السفلي، والقطعتان المعلمتان على الضلع العلوي متطابقتان.","answer":"A parallel through a midpoint bisects the other side: $x+3=\\frac32x+2$, hence $x=2$. Also $2y-1=3y-5$, so $y=4$.","answerAr":"المستقيم الموازي المار بمنتصف ضلع ينصف الضلع الآخر: $x+3=\\frac32x+2$، ومنه $x=2$. وكذلك $2y-1=3y-5$، لذلك $y=4$.","diagram":"week9-geometry","geometryDiagram":{"page":146,"number":12},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":146,"sourceQuestion":12,"expectedValues":{"x":2,"y":4},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"},{"label":"y · قيمة y — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p146-q13',$question_json${"id":"10a1-w9-p146-q13","classroom":"10A1","examWeek":9,"position":3,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 146 · Q13 · Proportional parts · الأجزاء المتناسبة","marks":3,"prompt":"$JH$ is a midsegment of $\\triangle KLM$. Find $x$. The full side LM is 30.","promptAr":"القطعة $JH$ قطعة متوسطة في $\\triangle KLM$. أوجد $x$. طول الضلع LM كاملاً هو 30.","answer":"A midsegment is half the parallel side: $x=\\frac{30}{2}=15$.","answerAr":"القطعة المتوسطة تساوي نصف الضلع الموازي: $x=\\frac{30}{2}=15$.","diagram":"week9-geometry","geometryDiagram":{"page":146,"number":13},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":146,"sourceQuestion":13,"expectedValues":{"x":15},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p146-q14',$question_json${"id":"10a1-w9-p146-q14","classroom":"10A1","examWeek":9,"position":4,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 146 · Q14 · Proportional parts · الأجزاء المتناسبة","marks":3,"prompt":"$JH$ is a midsegment of $\\triangle KLM$. Find $x$. The midsegment JH is 9.","promptAr":"القطعة $JH$ قطعة متوسطة في $\\triangle KLM$. أوجد $x$. طول القطعة المتوسطة JH هو 9.","answer":"The full side is twice the midsegment: $x=2(9)=18$.","answerAr":"الضلع الكامل ضعف القطعة المتوسطة: $x=2(9)=18$.","diagram":"week9-geometry","geometryDiagram":{"page":146,"number":14},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":146,"sourceQuestion":14,"expectedValues":{"x":18},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p146-q15',$question_json${"id":"10a1-w9-p146-q15","classroom":"10A1","examWeek":9,"position":5,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 146 · Q15 · Proportional parts · الأجزاء المتناسبة","marks":3,"prompt":"$JH$ is a midsegment of $\\triangle KLM$. Find $x$. The marked half of LM is 8; the full side LM is twice this length.","promptAr":"القطعة $JH$ قطعة متوسطة في $\\triangle KLM$. أوجد $x$. طول النصف المعلم من LM هو 8، وطول LM الكامل ضعف ذلك.","answer":"The marked half is 8, so $LM=16$ and $x=JH=\\frac{16}{2}=8$.","answerAr":"النصف المعلم يساوي 8، لذلك $LM=16$ و$x=JH=\\frac{16}{2}=8$.","diagram":"week9-geometry","geometryDiagram":{"page":146,"number":15},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":146,"sourceQuestion":15,"expectedValues":{"x":8},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p146-q16',$question_json${"id":"10a1-w9-p146-q16","classroom":"10A1","examWeek":9,"position":6,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 146 · Q16 · Proportional parts · الأجزاء المتناسبة","marks":3,"prompt":"In $\\triangle ABC$, $DE\\parallel AC$ and $DE=10$. If DE is a midsegment, find AC.","promptAr":"في $\\triangle ABC$، $DE\\parallel AC$ و$DE=10$. إذا كانت DE قطعة متوسطة فأوجد AC.","answer":"$DE=\\frac12AC$, so $AC=2(10)=20$. The stated midsegment length determines the answer.","answerAr":"$DE=\\frac12AC$، ومنه $AC=2(10)=20$. نعتمد طول القطعة المتوسطة المعطى في نص السؤال.","diagram":"week9-geometry","geometryDiagram":{"page":146,"number":16},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":146,"sourceQuestion":16,"expectedValues":{"AC":20},"responseParts":[{"label":"AC · قيمة AC — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q1',$question_json${"id":"10a1-w9-p153-q1","classroom":"10A1","examWeek":9,"position":7,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q1 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"Each pair of triangles is similar. Find x using corresponding sides and corresponding medians or altitudes. The corresponding side lengths are 7+7 and 5.25+5.25; the inner segments are 22 and x.","promptAr":"كل زوج من المثلثات متشابه. أوجد x باستعمال الأضلاع والقطع المتناظرة من المتوسطات أو الارتفاعات. طولا الضلعين المتناظرين هما 7+7 و5.25+5.25، والقطعتان الداخليتان 22 وx.","answer":"The side ratio is $\\frac{10.5}{14}=\\frac34$. Corresponding inner segments have the same ratio, so $x=22\\cdot\\frac34=16.5$.","answerAr":"نسبة الضلعين $\\frac{10.5}{14}=\\frac34$. وللقطعتين المتناظرتين النسبة نفسها، لذلك $x=22\\cdot\\frac34=16.5$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":1},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":1,"expectedValues":{"x":16.5},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q2',$question_json${"id":"10a1-w9-p153-q2","classroom":"10A1","examWeek":9,"position":8,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q2 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"Each pair of triangles is similar. Find x using corresponding sides and corresponding medians or altitudes. The corresponding bases are 15 and 10; the corresponding medians are 33 and x.","promptAr":"كل زوج من المثلثات متشابه. أوجد x باستعمال الأضلاع والقطع المتناظرة من المتوسطات أو الارتفاعات. القاعدتان المتناظرتان 15 و10، والمتوسطان المتناظران 33 وx.","answer":"$\\frac{x}{33}=\\frac{10}{15}$, hence $x=33\\cdot\\frac23=22$.","answerAr":"$\\frac{x}{33}=\\frac{10}{15}$، ومنه $x=33\\cdot\\frac23=22$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":2},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":2,"expectedValues":{"x":22},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q3',$question_json${"id":"10a1-w9-p153-q3","classroom":"10A1","examWeek":9,"position":9,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q3 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"Each pair of triangles is similar. Find x using corresponding sides and corresponding medians or altitudes. The corresponding altitudes are 20 and 10, and the corresponding sides are 22 and x.","promptAr":"كل زوج من المثلثات متشابه. أوجد x باستعمال الأضلاع والقطع المتناظرة من المتوسطات أو الارتفاعات. الارتفاعان المتناظران 20 و10، والضلعان المتناظران 22 وx.","answer":"$\\frac{x}{22}=\\frac{10}{20}$, so $x=11$.","answerAr":"$\\frac{x}{22}=\\frac{10}{20}$، ولذلك $x=11$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":3},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":3,"expectedValues":{"x":11},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q4',$question_json${"id":"10a1-w9-p153-q4","classroom":"10A1","examWeek":9,"position":10,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q4 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"Each pair of triangles is similar. Find x using corresponding sides and corresponding medians or altitudes. The corresponding medians are 18 and 12, and the corresponding sides are x and 12.6.","promptAr":"كل زوج من المثلثات متشابه. أوجد x باستعمال الأضلاع والقطع المتناظرة من المتوسطات أو الارتفاعات. المتوسطان المتناظران 18 و12، والضلعان المتناظران x و12.6.","answer":"$\\frac{x}{12.6}=\\frac{18}{12}$, so $x=18.9$.","answerAr":"$\\frac{x}{12.6}=\\frac{18}{12}$، ومنه $x=18.9$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":4},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":4,"expectedValues":{"x":18.9},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q5',$question_json${"id":"10a1-w9-p153-q5","classroom":"10A1","examWeek":9,"position":11,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q5 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"If $\\triangle RST\\sim\\triangle EFG$, SH is an altitude of RST and FJ is an altitude of EFG. Given $ST=6$, $SH=5$ and $FJ=7$, find FG.","promptAr":"إذا كان $\\triangle RST\\sim\\triangle EFG$ وSH ارتفاعاً في RST وFJ ارتفاعاً في EFG، وكان $ST=6$ و$SH=5$ و$FJ=7$، فأوجد FG.","answer":"$ST\\leftrightarrow FG$ and $SH\\leftrightarrow FJ$. Thus $\\frac{FG}{6}=\\frac75$ and $FG=8.4$.","answerAr":"$ST\\leftrightarrow FG$ و$SH\\leftrightarrow FJ$. إذن $\\frac{FG}{6}=\\frac75$ ومنه $FG=8.4$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":5},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":5,"expectedValues":{"FG":8.4},"responseParts":[{"label":"FG · قيمة FG — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q6',$question_json${"id":"10a1-w9-p153-q6","classroom":"10A1","examWeek":9,"position":12,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q6 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"If $\\triangle ABC\\sim\\triangle MNP$, AD is an altitude of ABC and MQ is an altitude of MNP. Given $AB=24$, $AD=14$ and $MQ=10.5$, find MN.","promptAr":"إذا كان $\\triangle ABC\\sim\\triangle MNP$ وAD ارتفاعاً في ABC وMQ ارتفاعاً في MNP، وكان $AB=24$ و$AD=14$ و$MQ=10.5$، فأوجد MN.","answer":"$\\frac{MN}{24}=\\frac{10.5}{14}=\\frac34$, so $MN=18$.","answerAr":"$\\frac{MN}{24}=\\frac{10.5}{14}=\\frac34$، ولذلك $MN=18$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":6},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":6,"expectedValues":{"MN":18},"responseParts":[{"label":"MN · قيمة MN — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q7',$question_json${"id":"10a1-w9-p153-q7","classroom":"10A1","examWeek":9,"position":13,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q7 · Similar triangles · المثلثات المتشابهة","marks":4,"prompt":"The intersection B of two paths forms two similar triangles. AC=50 yards and MP=35 yards. The fountain is 5 yards from B along the perpendicular to MP. How far is the stadium entrance from B along the corresponding perpendicular to AC? Round to the nearest yard.","promptAr":"يشكل تقاطع المسارين عند B مثلثين متشابهين. AC=50 ياردة وMP=35 ياردة، وتبعد النافورة 5 ياردات عن B على العمود على MP. ما بُعد مدخل الملعب عن B على العمود المناظر على AC؟ قرّب إلى أقرب ياردة.","answer":"Corresponding altitudes are proportional to the bases: $\\frac{h}{5}=\\frac{50}{35}$. Thus $h=\\frac{50}{7}\\approx7.14$, so the distance is about $7$ yards.","answerAr":"الارتفاعات المتناظرة تتناسب مع القواعد: $\\frac{h}{5}=\\frac{50}{35}$. إذن $h=\\frac{50}{7}\\approx7.14$، والمسافة نحو $7$ ياردات.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":7},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":7,"expectedValues":{"distance":7},"responseParts":[{"label":"Distance · المسافة — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q8',$question_json${"id":"10a1-w9-p153-q8","classroom":"10A1","examWeek":9,"position":14,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q8 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"The marked segment bisects the top angle. Find m to the nearest tenth. The opposite side is split into lengths 8 and 12; the right side is 20.","promptAr":"القطعة المعلمة تنصف الزاوية العليا. أوجد m إلى أقرب عُشر. قُسم الضلع المقابل إلى قطعتين 8 و12، وطول الضلع الأيمن 20.","answer":"By the Angle Bisector Theorem, $\\frac{m}{20}=\\frac8{12}$. Hence $m=\\frac{40}{3}\\approx13.3$.","answerAr":"وفق نظرية منصف الزاوية $\\frac{m}{20}=\\frac8{12}$، ومنه $m=\\frac{40}{3}\\approx13.3$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":8},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":8,"expectedValues":{"m":13.3},"responseParts":[{"label":"m · قيمة m — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q9',$question_json${"id":"10a1-w9-p153-q9","classroom":"10A1","examWeek":9,"position":15,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q9 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"The marked segment bisects the left angle. Find x to the nearest tenth. The adjacent sides are 24 and 20, and the opposite side is split into x and 7.","promptAr":"القطعة المعلمة تنصف الزاوية اليسرى. أوجد x إلى أقرب عُشر. طولا الضلعين المجاورين 24 و20، وقُسم الضلع المقابل إلى x و7.","answer":"$\\frac{x}{7}=\\frac{24}{20}$, so $x=8.4$.","answerAr":"$\\frac{x}{7}=\\frac{24}{20}$، ومنه $x=8.4$.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":9},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":9,"expectedValues":{"x":8.4},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q10',$question_json${"id":"10a1-w9-p153-q10","classroom":"10A1","examWeek":9,"position":16,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q10 · Similar triangles · المثلثات المتشابهة","marks":4,"prompt":"For this question, $\\triangle ABC\\sim\\triangle DEF$. BX and EY are corresponding altitudes, $AB=12$ cm, $BX=8$ cm, $AC=14$ cm and $DE=8$ cm. Find XC to the nearest tenth.","promptAr":"في هذا السؤال $\\triangle ABC\\sim\\triangle DEF$، وBX وEY ارتفاعان متناظران، و$AB=12$ سم و$BX=8$ سم و$AC=14$ سم و$DE=8$ سم. أوجد XC إلى أقرب عُشر.","answer":"In right triangle ABX, $AX=\\sqrt{12^2-8^2}=\\sqrt{80}=4\\sqrt5$. Hence $XC=14-4\\sqrt5\\approx5.1$ cm.","answerAr":"في المثلث القائم ABX، $AX=\\sqrt{12^2-8^2}=4\\sqrt5$. إذن $XC=14-4\\sqrt5\\approx5.1$ سم.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":10},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":10,"expectedValues":{"XC":5.1},"responseParts":[{"label":"XC · قيمة XC — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p153-q11',$question_json${"id":"10a1-w9-p153-q11","classroom":"10A1","examWeek":9,"position":17,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 153 · Q11 · Similar triangles · المثلثات المتشابهة","marks":3,"prompt":"For this question, $\\triangle ABC\\sim\\triangle DEF$. BX and EY are corresponding altitudes, $AB=12$ cm, $BX=8$ cm, $AC=14$ cm and $DE=8$ cm. Find EY to the nearest tenth.","promptAr":"في هذا السؤال $\\triangle ABC\\sim\\triangle DEF$، وBX وEY ارتفاعان متناظران، و$AB=12$ سم و$BX=8$ سم و$AC=14$ سم و$DE=8$ سم. أوجد EY إلى أقرب عُشر.","answer":"The scale factor from ABC to DEF is $\\frac{DE}{AB}=\\frac8{12}=\\frac23$. Thus $EY=8\\cdot\\frac23=\\frac{16}{3}\\approx5.3$ cm.","answerAr":"معامل التشابه من ABC إلى DEF هو $\\frac{DE}{AB}=\\frac8{12}=\\frac23$. ومنه $EY=8\\cdot\\frac23=\\frac{16}{3}\\approx5.3$ سم.","diagram":"week9-geometry","geometryDiagram":{"page":153,"number":11},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":153,"sourceQuestion":11,"expectedValues":{"EY":5.3},"responseParts":[{"label":"EY · قيمة EY — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p165-q1',$question_json${"id":"10a1-w9-p165-q1","classroom":"10A1","examWeek":9,"position":18,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q1 · Geometric mean · الوسط الهندسي","marks":2,"prompt":"Find the geometric mean between $4$ and $6$. Give the positive exact value in simplest radical form.","promptAr":"أوجد الوسط الهندسي بين $4$ و$6$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{24}=2\\sqrt6$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{24}=2\\sqrt6$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":1,"expectedValues":{"mean":4.898979485566356},"responseParts":[{"label":"Geometric mean · الوسط الهندسي — show working · وضح خطوات الحل"}],"geometricMean":[4,6]}$question_json$::jsonb),
('10a1-w9-p165-q2',$question_json${"id":"10a1-w9-p165-q2","classroom":"10A1","examWeek":9,"position":19,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q2 · Geometric mean · الوسط الهندسي","marks":2,"prompt":"Find the geometric mean between $\\frac12$ and $2$. Give the positive exact value in simplest radical form.","promptAr":"أوجد الوسط الهندسي بين $\\frac12$ و$2$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{1}=1$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{1}=1$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":2,"expectedValues":{"mean":1},"responseParts":[{"label":"Geometric mean · الوسط الهندسي — show working · وضح خطوات الحل"}],"geometricMean":[0.5,2]}$question_json$::jsonb),
('10a1-w9-p165-q3',$question_json${"id":"10a1-w9-p165-q3","classroom":"10A1","examWeek":9,"position":20,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q3 · Geometric mean · الوسط الهندسي","marks":2,"prompt":"Find the geometric mean between $4$ and $25$. Give the positive exact value in simplest radical form.","promptAr":"أوجد الوسط الهندسي بين $4$ و$25$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{100}=10$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{100}=10$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":3,"expectedValues":{"mean":10},"responseParts":[{"label":"Geometric mean · الوسط الهندسي — show working · وضح خطوات الحل"}],"geometricMean":[4,25]}$question_json$::jsonb),
('10a1-w9-p165-q4',$question_json${"id":"10a1-w9-p165-q4","classroom":"10A1","examWeek":9,"position":21,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q4 · Geometric mean · الوسط الهندسي","marks":2,"prompt":"Find the geometric mean between $12$ and $20$. Give the positive exact value in simplest radical form.","promptAr":"أوجد الوسط الهندسي بين $12$ و$20$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{240}=4\\sqrt{15}$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{240}=4\\sqrt{15}$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":4,"expectedValues":{"mean":15.491933384829668},"responseParts":[{"label":"Geometric mean · الوسط الهندسي — show working · وضح خطوات الحل"}],"geometricMean":[12,20]}$question_json$::jsonb),
('10a1-w9-p165-q5',$question_json${"id":"10a1-w9-p165-q5","classroom":"10A1","examWeek":9,"position":22,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q5 · Geometric mean · الوسط الهندسي","marks":2,"prompt":"Find the geometric mean between $17$ and $3$. Give the positive exact value in simplest radical form.","promptAr":"أوجد الوسط الهندسي بين $17$ و$3$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{51}=\\sqrt{51}$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{51}=\\sqrt{51}$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":5,"expectedValues":{"mean":7.14142842854285},"responseParts":[{"label":"Geometric mean · الوسط الهندسي — show working · وضح خطوات الحل"}],"geometricMean":[17,3]}$question_json$::jsonb),
('10a1-w9-p165-q6',$question_json${"id":"10a1-w9-p165-q6","classroom":"10A1","examWeek":9,"position":23,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q6 · Geometric mean · الوسط الهندسي","marks":2,"prompt":"Find the geometric mean between $3$ and $24$. Give the positive exact value in simplest radical form.","promptAr":"أوجد الوسط الهندسي بين $3$ و$24$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{72}=6\\sqrt2$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{72}=6\\sqrt2$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":6,"expectedValues":{"mean":8.48528137423857},"responseParts":[{"label":"Geometric mean · الوسط الهندسي — show working · وضح خطوات الحل"}],"geometricMean":[3,24]}$question_json$::jsonb),
('10a1-w9-p165-q11',$question_json${"id":"10a1-w9-p165-q11","classroom":"10A1","examWeek":9,"position":24,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q11 · Geometric mean · الوسط الهندسي","marks":6,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; you may also give decimal checks to the nearest tenth. The hypotenuse is split into lengths 8 and 23.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. قُسم الوتر إلى قطعتين طولهما 8 و23.","answer":"The hypotenuse is $c=8+23=31$. Altitude: $x^2=8(23)$, so $x=2\\sqrt{46}\\approx13.6$. Legs: $y^2=31(8)$, so $y=2\\sqrt{62}\\approx15.7$; $z^2=31(23)$, so $z=\\sqrt{713}\\approx26.7$.","answerAr":"الوتر $c=8+23=31$. للارتفاع $x^2=8(23)$، ومنه $x=2\\sqrt{46}\\approx13.6$. وللضلعين $y^2=31(8)$، لذلك $y=2\\sqrt{62}\\approx15.7$؛ و$z^2=31(23)$، لذلك $z=\\sqrt{713}\\approx26.7$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":11},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":11,"expectedValues":{"x":13.564659966250536,"y":15.748015748023622,"z":26.70205984563738},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"},{"label":"y · قيمة y — show working · وضح خطوات الحل"},{"label":"z · قيمة z — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p165-q12',$question_json${"id":"10a1-w9-p165-q12","classroom":"10A1","examWeek":9,"position":25,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q12 · Geometric mean · الوسط الهندسي","marks":6,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; you may also give decimal checks to the nearest tenth. The whole hypotenuse is 25 and its right-hand segment is 6.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. طول الوتر كاملاً 25 وطول جزئه الأيمن 6.","answer":"The other hypotenuse segment is $25-6=19$. $x^2=19(6)$ gives $x=\\sqrt{114}\\approx10.7$. $y^2=25(6)$ gives $y=5\\sqrt6\\approx12.2$. $z^2=25(19)$ gives $z=5\\sqrt{19}\\approx21.8$.","answerAr":"جزء الوتر الآخر $25-6=19$. من $x^2=19(6)$ نحصل على $x=\\sqrt{114}\\approx10.7$. ومن $y^2=25(6)$ نحصل على $y=5\\sqrt6\\approx12.2$. ومن $z^2=25(19)$ نحصل على $z=5\\sqrt{19}\\approx21.8$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":12},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":12,"expectedValues":{"x":10.677078252031311,"y":12.24744871391589,"z":21.79449471770337},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"},{"label":"y · قيمة y — show working · وضح خطوات الحل"},{"label":"z · قيمة z — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p165-q13',$question_json${"id":"10a1-w9-p165-q13","classroom":"10A1","examWeek":9,"position":26,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q13 · Geometric mean · الوسط الهندسي","marks":6,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; you may also give decimal checks to the nearest tenth. The altitude is 3; the left hypotenuse segment is 2, the right segment is x, the whole hypotenuse is z, and the left leg is y.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. طول الارتفاع 3، وجزء الوتر الأيسر 2 والأيمن x، وطول الوتر كاملاً z، والضلع الأيسر y.","answer":"Altitude theorem: $3^2=2x$, so $x=\\frac92=4.5$. Thus $z=2+x=\\frac{13}{2}=6.5$. Leg theorem: $y^2=2z=13$, so $y=\\sqrt{13}\\approx3.6$.","answerAr":"من نظرية الارتفاع $3^2=2x$، لذلك $x=\\frac92=4.5$. ومنه $z=2+x=\\frac{13}{2}=6.5$. وبنظرية الضلع $y^2=2z=13$، لذلك $y=\\sqrt{13}\\approx3.6$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":13},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":13,"expectedValues":{"x":4.5,"y":3.605551275463989,"z":6.5},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"},{"label":"y · قيمة y — show working · وضح خطوات الحل"},{"label":"z · قيمة z — show working · وضح خطوات الحل"}]}$question_json$::jsonb),
('10a1-w9-p165-q14',$question_json${"id":"10a1-w9-p165-q14","classroom":"10A1","examWeek":9,"position":27,"type":"FRQ","exam":"EOT · 10A1 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 165 · Q14 · Geometric mean · الوسط الهندسي","marks":6,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; you may also give decimal checks to the nearest tenth. The whole hypotenuse is 20 and the right leg is 10. The hypotenuse parts are x and y; the left leg is z.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. طول الوتر كاملاً 20 والضلع الأيمن 10. جزآ الوتر هما x وy، وطول الضلع الأيسر z.","answer":"Leg theorem: $10^2=20y$, so $y=5$. Hence $x=20-5=15$. Then $z^2=20(15)=300$, so $z=10\\sqrt3\\approx17.3$.","answerAr":"من نظرية الضلع $10^2=20y$، ومنه $y=5$. إذن $x=20-5=15$. ثم $z^2=20(15)=300$، لذلك $z=10\\sqrt3\\approx17.3$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":14},"difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":165,"sourceQuestion":14,"expectedValues":{"x":15,"y":5,"z":17.320508075688775},"responseParts":[{"label":"x · قيمة x — show working · وضح خطوات الحل"},{"label":"y · قيمة y — show working · وضح خطوات الحل"},{"label":"z · قيمة z — show working · وضح خطوات الحل"}]}$question_json$::jsonb)
ON CONFLICT(id) DO NOTHING;
